def deep_dict_update(main_dict: Dict[Any, Any], update_dict: Dict[Any, Any]) -> None:
    """
    Recursively updates main_dict with the key-value pairs from update_dict.
    If a key in update_dict has a value that is a dictionary, it will recursively
    update the corresponding value in main_dict. If the key does not exist in
    main_dict, it will be added.
    """
    for key, value in update_dict.items():
        if isinstance(value, dict):
            # If the value is a dictionary, ensure the key exists in main_dict
            if key not in main_dict:
                main_dict[key] = {}
            # Recursively update the dictionary
            deep_dict_update(main_dict[key], value)
        else:
            # Otherwise, directly update the value
            main_dict[key] = value
